let etat = null, actuel = null, vue = 'alertes', vus = {}, attenteReponse = 0, rapideJusqua = 0, derniereActivite = Date.now(), enCours = false, derniereSignature = '', dernierCoupOeil = 0;
const $ = (s) => document.querySelector(s);
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const lire = (k) => { try { return localStorage.getItem(k); } catch (e) { return null; } };
const ecrire = (k, v) => { try { localStorage.setItem(k, v); } catch (e) {} };
const hhmm = (h) => String(h || '').replace(/^(\d+) h (\d+)$/, '$1:$2').replace(/^(\d+) h$/, '$1:00');

function toast(t) { const el = $('#toast'); el.textContent = t; el.classList.add('oui'); clearTimeout(toast.t); toast.t = setTimeout(() => el.classList.remove('oui'), 4200); }
function erreur(t) { const el = $('#erreur'); el.textContent = t || ''; el.classList.toggle('oui', !!t); }
function activite(rapide) { derniereActivite = Date.now(); if (rapide) rapideJusqua = Date.now() + 16000; }

async function poster(chemin, donnees) {
  activite(true);
  const corps = new URLSearchParams(Object.assign({ cle: CLE }, donnees));
  const r = await fetch(BASE + chemin, { method: 'POST', body: corps });
  if (!r.ok) throw new Error('HTTP ' + r.status);
  const type = r.headers.get('content-type') || '';
  return type.includes('json') ? r.json() : r.text();
}

async function charger() {
  try {
    const r = await fetch(BASE + 'vx-accueil-etat?cle=' + encodeURIComponent(CLE) + '&t=' + Date.now(), { cache: 'no-store' });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    etat = await r.json();
