    // la page reste en direct même quand on manipule son téléphone plutôt que la page.
    const { horloge, ...contenu } = etat;
    const signature = JSON.stringify(contenu);
    if (derniereSignature && signature !== derniereSignature) activite(false);
    derniereSignature = signature;
    erreur('');
    rendre();
  } catch (e) { erreur('Connexion au circuit n8n impossible pour le moment (' + e.message + '). Nouvel essai automatique…'); }
}

function boucle() {
  const maintenant = Date.now();
  // Veille après 4 min sans rien (30 min quand un vrai portable est branché : on regarde son téléphone).
  const limite = (etat && etat.smsReels ? 30 : 4) * 60 * 1000;
  const actif = maintenant - derniereActivite < limite;
  if (document.hidden) { setTimeout(boucle, 1500); return; }
  // En veille, un coup d'œil toutes les 20 s : un vrai appel ou un vrai SMS apparaît quand même,
  // et ce changement réveille la page (voir charger()).
  if (!actif) {
    if (maintenant - dernierCoupOeil < 20000) { setTimeout(boucle, 1500); return; }
    dernierCoupOeil = maintenant;
  }
  const delai = maintenant < rapideJusqua ? 900 : 4000;
  charger().finally(() => setTimeout(boucle, delai));
}
document.addEventListener('pointerdown', () => activite(false));
document.addEventListener('keydown', () => activite(false));

// ---------- Rendu
function rendre() {
