  html += '<div class="ecrit' + (attenteReponse > Date.now() ? ' oui' : '') + '" id="ecrit"><i></i><i></i><i></i></div>';
  const cle = actuel + '|' + fil.length + '|' + (attenteReponse > Date.now());
  const el = $('#fil');
  if (cle !== dernierRendu) {
    const enBas = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
    el.innerHTML = html;
    if (enBas || true) el.scrollTop = el.scrollHeight;
    dernierRendu = cle;
  }
  const dernier = fil.filter((m) => m.sens === 'sortant').pop();
  if (dernier && fil.length && fil[fil.length - 1].sens === 'sortant') attenteReponse = 0;
  // Vrai portable : avec de vrais SMS, on regarde ici et on répond depuis le téléphone.
  // SMS simulés (compte d'essai) : son vrai appel arrive ici, et on lui répond depuis la page.
  const p = etat.personnes.find((x) => x.numero === actuel);
  const reel = !!(p && p.role === 'reel');
  const lecture = reel && !!etat.smsReels;
  $('#f-sms').style.display = lecture ? 'none' : '';
  $('#lecture').style.display = lecture ? '' : 'none';
  $('#simule').style.display = reel && !lecture ? '' : 'none';
  rendreReponses(lecture ? null : dernier);
}

function rendreReponses(dernier) {
  let puces = [];
  const c = dernier ? dernier.contexte : '';
  if (c === 'creneaux') puces = ['1', '2', '3', 'AUTRE'];
  else if (c === 'rappel-veille' || c === 'rappel-jour') puces = ['OUI', 'DEPLACER', 'ANNULER'];
  else if (c === 'offre-attente') puces = ['OUI'];
  else if (c === 'relance-absent' || c === 'annulation') puces = ['RDV'];
