  else if (c === 'appel-manque' || c === 'appel-manque-nuit') puces = ['URGENT'];
  $('#reponses').innerHTML = puces.map((p) => '<button class="puce" data-puce="' + esc(p) + '">' + esc(p) + '</button>').join('');
