function rendreResp() {
  const el = $('#panneau');
  let html = '';
  if (vue === 'alertes') {
    if (!etat.alertes.length) html = '<div class="vide">Aucune alerte pour l\'instant.<br>Elles arrivent ici et sur le vrai téléphone du responsable.</div>';
    for (const a of etat.alertes) {
