        + (r.rappelVeille ? '<span class="badge">Rappel veille ✓</span>' : '') + (r.rappelJour ? '<span class="badge">Rappel jour J ✓</span>' : '')
        + (r.confirme ? '<span class="badge ok">Confirmé ✓</span>' : '') + (r.passe ? '<span class="badge">Passé</span>' : '') + '</div></div></div>';
    }
  } else {
