    for (const a of etat.attente) {
      html += '<div class="rdv attente"><div class="h">' + (a.statut === 'propose' ? 'Offre<b>envoyée</b>' : 'En<b>attente</b>') + '</div><div><div class="n">' + esc(a.nom) + '</div><div class="a">' + esc(a.besoin || '') + '</div></div></div>';
    }
  }
  if (el.dataset.html !== html) { el.innerHTML = html; el.dataset.html = html; }
}

function rendreChiffres() {
  const c = etat.compteurs;
  const t = [['appelsManques', 'appels manqués'], ['smsEnvoyes', 'SMS envoyés'], ['rdvPris', 'rendez-vous pris', 1], ['rappels', 'rappels envoyés'], ['revendus', 'places revendues', 1], ['urgences', 'urgences signalées']];
  $('#chiffres').innerHTML = t.map(([k, l, v]) => '<div class="chiffre' + (v ? ' vert' : '') + '"><b>' + (c[k] || 0) + '</b><span>' + l + '</span></div>').join('');
}

function rendreEtapes() {
  const c = etat.compteurs;
  const fait = { e1: c.appelsManques > 0, e2: c.rdvPris > 0, e3: (etat.agenda || []).some((r) => r.rappelVeille), e4: (etat.agenda || []).some((r) => r.rappelJour), e5: c.revendus > 0 };
  for (const [id, f] of Object.entries(fait)) $('#' + id).classList.toggle('faite', !!f);
}

// ---------- Actions
async function envoyerSms(texte, numero) {
  texte = String(texte || '').trim();
  if (!texte) return;
  const num = numero || actuel;
  if (num === actuel) { attenteReponse = Date.now() + 15000; }
  if (etat) {
    (etat.fils[num] = etat.fils[num] || []).push({ id: 'local', sens: 'entrant', canal: 'sms', texte, jour: etat.horloge.jour, heure: etat.horloge.heure, statut: 'recu' });
