}

async function appeler(qui) {
  let from = actuel;
  if (qui === 'masque') from = 'anonymous';
  if (qui === 'fournisseur') from = ((etat && etat.contacts) || []).find((c) => c.type === 'fournisseur').numero;
  if (qui === 'client') { from = etat.personnes.find((p) => p.role === 'client').numero; selectionner(from); attenteReponse = Date.now() + 9000; }
