}

async function action(nom, extra) {
  const boutons = document.querySelectorAll('[data-action],[data-horloge]');
  boutons.forEach((b) => (b.disabled = true));
  try {
    const r = await poster('vx-accueil-action', Object.assign({ action: nom }, extra || {}));
    if (r && r.info) toast(r.info);
